//! ABDrum as a CLAP / VST3 plugin.
//!
//! The sound is the Faust voice and effects in ../dsp, compiled to Rust
//! (`dsp.rs`, `fx.rs`, generated by tools/gen-rust.sh: don't edit them by hand). This crate adds
//! the engine (overlapping hits, choke), host parameters derived from the
//! Faust controls (`params`), the panel (`editor`) with its scopes
//! (`scope`), and the nih-plug wrapper below.

use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;

use nih_plug::prelude::*;

mod dsp {
    #![allow(warnings, clippy::all)]
    use faust_types::*;

    /// The Faust code reads the noise loops through this external function.
    #[inline(always)]
    fn sl_loop(index: i32, position: f32) -> f32 {
        crate::samplelib::read_loop(index, position)
    }

    /// ... and the sample layers' hits through this one.
    #[inline(always)]
    fn sl_hit(index: i32, position: f32) -> f32 {
        crate::samplelib::read_hit(index, position)
    }

    include!("dsp.rs");
}
mod body {
    #![allow(warnings, clippy::all)]
    use faust_types::*;

    include!("body.rs");
}
mod noise {
    #![allow(warnings, clippy::all)]
    use faust_types::*;

    /// The Noise reads its loops through this external function.
    #[inline(always)]
    fn sl_loop(index: i32, position: f32) -> f32 {
        crate::samplelib::read_loop(index, position)
    }

    include!("noise.rs");
}
mod fx {
    #![allow(warnings, clippy::all)]
    use faust_types::*;

    include!("fx.rs");
}
pub mod editor;
pub mod engine;
pub mod export;
pub mod scope;
pub mod params;
pub mod samplelib;

use engine::{Engine, Limiter, MAX_BLOCK};
use params::DrumParams;
use scope::HitScope;

pub struct ABDrum {
    params: Arc<DrumParams>,
    /// The latest hit's parts, for the panel's scopes.
    scope: Arc<HitScope>,
    /// The output's peak since the panel last read it (f32 bits).
    meter: Arc<AtomicU32>,
    /// The host's sample rate (f32 bits), for the panel's exports.
    sample_rate: Arc<AtomicU32>,
    engine: Engine,
    limiter: Limiter,
    mono: [f32; MAX_BLOCK],
}

impl Default for ABDrum {
    fn default() -> Self {
        let params = Arc::new(DrumParams::from_faust());
        let mut engine = Engine::new(params.slots());
        let scope = Arc::new(HitScope::default());
        engine.recorder.share(scope.clone());
        let sample_rate = Arc::new(AtomicU32::new(48_000f32.to_bits()));
        Self { params, scope, meter: Arc::default(), sample_rate, engine, limiter: Limiter::new(), mono: [0.0; MAX_BLOCK] }
    }
}

impl ABDrum {
    fn handle(&mut self, event: NoteEvent<()>) {
        match event {
            NoteEvent::NoteOn { note, velocity, .. } => self.engine.note_on(note, velocity),
            // Note-offs are ignored: a hit rings for as long as its envelopes say.
            NoteEvent::Choke { .. } => self.engine.choke(),
            _ => (),
        }
    }
}

impl Plugin for ABDrum {
    const NAME: &'static str = "ABDrum";
    const VENDOR: &'static str = "Abdicant";
    const URL: &'static str = "";
    const EMAIL: &'static str = "";
    const VERSION: &'static str = env!("CARGO_PKG_VERSION");

    const AUDIO_IO_LAYOUTS: &'static [AudioIOLayout] = &[AudioIOLayout {
        main_input_channels: None,
        main_output_channels: NonZeroU32::new(2),
        ..AudioIOLayout::const_default()
    }];

    const MIDI_INPUT: MidiConfig = MidiConfig::Basic;
    const SAMPLE_ACCURATE_AUTOMATION: bool = true;

    type SysExMessage = ();
    type BackgroundTask = ();

    fn params(&self) -> Arc<dyn Params> {
        self.params.clone()
    }

    fn editor(&mut self, _executor: AsyncExecutor<Self>) -> Option<Box<dyn Editor>> {
        editor::create(self.params.clone(), self.scope.clone(), self.meter.clone(), self.sample_rate.clone())
    }

    fn initialize(&mut self, _layout: &AudioIOLayout, config: &BufferConfig, _context: &mut impl InitContext<Self>) -> bool {
        self.engine.init(config.sample_rate);
        self.sample_rate.store(config.sample_rate.to_bits(), Ordering::Relaxed);
        self.limiter.init(config.sample_rate);
        true
    }

    fn reset(&mut self) {
        self.engine.reset();
    }

    fn process(&mut self, buffer: &mut Buffer, _aux: &mut AuxiliaryBuffers, context: &mut impl ProcessContext<Self>) -> ProcessStatus {
        let total = buffer.samples();
        let output = buffer.as_slice();
        let mut next_event = context.next_event();
        let mut start = 0;

        while start < total {
            // Apply every event due by now; end this sub-block at the next one.
            let mut end = (start + MAX_BLOCK).min(total);
            while let Some(event) = next_event {
                let at = event.timing() as usize;
                if at <= start {
                    self.handle(event);
                    next_event = context.next_event();
                } else {
                    end = end.min(at);
                    break;
                }
            }

            // Faust smooths its own controls, so plain values per block are enough.
            self.engine.apply(&self.params);

            let n = end - start;
            self.engine.render(&mut self.mono[..n]);
            let mut peak = 0.0f32;
            for (i, s) in self.mono[..n].iter().enumerate() {
                let out = self.limiter.process(s * self.params.volume.smoothed.next());
                output[0][start + i] = out;
                output[1][start + i] = out;
                peak = peak.max(out.abs());
            }
            // Positive floats order like their bits, so fetch_max keeps the peak.
            self.meter.fetch_max(peak.to_bits(), Ordering::Relaxed);
            start = end;
        }

        ProcessStatus::Normal
    }
}

impl ClapPlugin for ABDrum {
    const CLAP_ID: &'static str = "local.abdicant.abdrum";
    const CLAP_DESCRIPTION: Option<&'static str> = Some("Personal drum synthesizer");
    const CLAP_MANUAL_URL: Option<&'static str> = None;
    const CLAP_SUPPORT_URL: Option<&'static str> = None;
    const CLAP_FEATURES: &'static [ClapFeature] = &[ClapFeature::Instrument, ClapFeature::Drum, ClapFeature::Stereo];
}

impl Vst3Plugin for ABDrum {
    const VST3_CLASS_ID: [u8; 16] = *b"ABDrumAbdicant01";
    const VST3_SUBCATEGORIES: &'static [Vst3SubCategory] =
        &[Vst3SubCategory::Instrument, Vst3SubCategory::Drum, Vst3SubCategory::Stereo];
}

nih_export_clap!(ABDrum);
nih_export_vst3!(ABDrum);
